        result*=value;
    }

    function divide(uint value) external{
        result/=value;
    }

    function modulo(uint value) external{
        result%=value;
    }

    function square(uint value) external{
        result = value * value;
    }

    function sqrt(uint value) external{
        if(value>3){
           result = value;
           uint x = value / 2 + 1;
           while(x>result){
            result = x;
            x = (value / x + x) / 2;
           }
         }else if (value !=0){
            result=1;
         }else 
         result=0;
    }

}

