    function withdraw(uint amount) public {
        if (amount > balance) {
            revert("Insufficient balance"); //  custom condition
        }

        balance -= amount;

        // Internal safety check
        assert(balance >= 0 && balance>=400);//balance should be greater than 400
    }
}

