// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract currencyConversion{
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    mapping(string => uint) public rates;

    function setRate(string memory currency, uint rate) external onlyOwner {
        rates[currency] = rate;
    }

    function convert(string memory currency, uint amount) external view returns (uint) {
        uint rate = rates[currency];
        require(rate > 0, "Rate not set");

        return amount * rate; 
    } 
}

Practice/19 may/HospitalManagement.sol.content:
// Blockchain Hospital Management System
// Create a smart contract named HospitalManagement.
// Patient Details
// patientId
// name
// disease
// doctorAssigned
// admitted
// billAmount
// Add patient
// Update disease
// Assign doctor
// Discharge patient
// Generate hospital bill
// Prevent updating discharged patient
// Count admitted patients
// Get patient details

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract HospitalManagement {
    struct Patient {
        uint patientId;
        string name;
        string disease;
        string doctorAssigned;
        bool admitted;
        uint billAmount;
    }

    mapping (uint => Patient) public patients;
    mapping (uint => bool) public ispatientExist;
    uint public totalAdmittedPatients;
    uint public totalpatients;

    function addPatient(uint _patientId,string memory _name) public{
       require(ispatientExist[_patientId]==false,"Already Existed");
       totalpatients++;
       ispatientExist[_patientId] = true;
       patients[_patientId] = Patient(_patientId,_name,"","",false,500);
    }

    function updatePatientDisease(uint _patientId,string memory _disease) public{
       require(ispatientExist[_patientId]==true,"Not Existed");
       patients[_patientId].disease = _disease;
    }

     function admitPatient(uint _patientId) public{
       require(ispatientExist[_patientId]==true,"Not Existed");
       patients[_patientId].admitted = true;
       totalAdmittedPatients++;
       patients[_patientId].billAmount += 2000;
    }

    function assignDoctor(uint _patientId,string memory _doctor) public{
       require(ispatientExist[_patientId]==true,"Not Existed");
       patients[_patientId].doctorAssigned = _doctor;
       patients[_patientId].billAmount += 500;
    }

    function generateHospitalBill(uint _patientId) public view returns(string memory name, uint billAmount){
       require(ispatientExist[_patientId]==true,"Not Existed");
       Patient memory p = patients[_patientId];
        return (p.name, p.billAmount);
    }

    function discharge(uint _patientId) public{
       require(ispatientExist[_patientId]==true,"Not Existed");
       totalAdmittedPatients--;
       patients[_patientId].admitted = false;
    }
}

Practice/CourseRegistration.sol.content:
// Course -
// courseId
// courseName
// teacherName
// totalSeats
// enrolledStudents
// Student
// studentId
// name
// enrolled
// Requirements -
// Add new course
// Register student in course
// Prevent over-enrollment
// Prevent same student registering twice
// Track total enrolled students
// Get course details
// Get student details

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract CourseRegistration {
    struct Course {
        uint courseId;
        string courseName;
        string teacherName;
        uint totalSeats;
        uint enrolledStudents;
    }

    struct Student {
        uint studentId;
        string name;
        uint courseId;
        bool enrolled;
    }
    uint totalCourses;
    uint totalStudents;
    mapping(uint => Course) public courses;
    mapping(uint => Student) public students;
    mapping(uint => bool) public isStudentExist;

    function addCourse(
        string memory _courseName,
        string memory _teacherName,
        uint _totalseats
    ) public {
        totalCourses++;
        courses[totalCourses] = Course(
            totalCourses,
            _courseName,
            _teacherName,
            _totalseats,
            0
        );
    }

    function addStudent_Course(
        uint _courseId,
        uint _studentId,
        string memory _Name
    ) public {
        require(
            courses[_courseId].totalSeats > courses[_courseId].enrolledStudents,
            "No seat available"
        );
        require(isStudentExist[_studentId] == false, "Already Existed");
        totalStudents++;
        students[_studentId] = Student(_studentId, _Name, _courseId, true);
        courses[_courseId].enrolledStudents++;
        isStudentExist[_studentId] = true;
    }

    function getCourseDetails(
        uint _courseId
    ) public view returns (uint Id, string memory Name, string memory Teacher_Name, uint Total_seats, uint Enrolled_Students) {
        Course memory c = courses[_courseId];
        return (
            c.courseId,
            c.courseName,
            c.teacherName,
            c.totalSeats,
            c.enrolledStudents
        );
    }

    function getStudentDetails(
        uint _studentId
    ) public view returns (uint Id, string memory Name,uint CourseId, bool Enrolled) {
